"""The Swift evaluation window pack (scripts/ci/references/fusion-jobs/SW, generated by make_swift_jobs.py).

ORDER.txt lists exactly the folder's templates, each once, on the one image, with a total that matches its header; every NEEDS line names earlier jobs; the jobs that serve Swift carry the
two checkpoint keys and the jobs that serve the base carry neither; every smoke job runs the approved ship-4 profile (or its audited twin for SA1) with the smoke test the eight-seat rule
requires; every template parses through the job reader with rc 0; the pack is what the generator makes; and nothing in it names a host, an address or a registry.
"""

import json
import re
import subprocess
import sys
import unittest
from pathlib import Path

HERE = Path(__file__).resolve().parent
if str(HERE) not in sys.path:
    sys.path.insert(0, str(HERE))

import c2_serving_job as job  # noqa: E402
import make_swift_jobs as pack  # noqa: E402

PACK = pack.FOLDER
READER = HERE / 'c2_serving_job.py'
PROFILES = HERE / 'qwen_c2_profiles.json'
CATALOG = json.loads((HERE / 'qwen_c2_checkpoints.json').read_text(encoding='utf-8'))
SWIFT = CATALOG['checkpoints'][0]

# job -> (mode, serves Swift, profile, smoke tests)
EXPECTED = {
    'B0-build-window': ('stop', False, '', ''),
    'X0-status-rescan-reset': ('stop', False, '', ''),
    'W0-swift-first-boot': ('stop', True, pack.SHIP, pack.FIRST_BOOT_TESTS),
    'SW1-swift-smoke': ('stop', True, pack.SHIP, pack.SMOKE_TESTS),
    'SB1-base-smoke': ('soft', False, pack.SHIP, pack.SMOKE_TESTS),
    'T1-tau-base': ('soft', False, '', ''),
    'T2-tau-swift': ('soft', True, '', ''),
    'C1-base-a': ('soft', False, pack.SHIP, pack.DECODE_TESTS),
    'L1-swift-a': ('soft', True, pack.SHIP, pack.DECODE_TESTS),
    'C2-base-b': ('soft', False, pack.SHIP, pack.DECODE_TESTS),
    'L2-swift-b': ('soft', True, pack.SHIP, pack.DECODE_TESTS),
    'SA1-swift-audited-attach': ('soft', True, pack.AUDIT, 'warmup,coding,parked_turns,prefill_ladder_solo,concurrent8_steady'),
    'Z-reset': ('soft', False, '', ''),
}


def order_lines():
    return [line.split() for line in (PACK / 'ORDER.txt').read_text(encoding='utf-8').splitlines() if line.strip() and not line.startswith('#')]


def directives(prefix):
    return [line[len(prefix):].split() for line in (PACK / 'ORDER.txt').read_text(encoding='utf-8').splitlines() if line.startswith(prefix)]


def values(name):
    return job.parse_env((PACK / (name + '.env')).read_text(encoding='utf-8'))


def run_reader(path):
    result = subprocess.run([sys.executable, '-B', '-s', str(READER), str(path), str(PROFILES)], stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=str(HERE.parent.parent))
    return result.returncode, (result.stdout + result.stderr).decode('utf-8', 'replace')


class OrderTests(unittest.TestCase):
    def test_order_lists_exactly_the_folders_templates_once_on_one_image(self):
        rows = order_lines()
        self.assertEqual([row[0] for row in rows], list(EXPECTED), 'in value order')
        self.assertEqual(sorted(path.stem for path in PACK.glob('*.env')), sorted(EXPECTED))
        self.assertEqual({row[2] for row in rows}, {pack.IMAGE})
        for row in rows:
            self.assertEqual(row[1], EXPECTED[row[0]][0], row[0])
            self.assertEqual(values(row[0])['C2_IMAGE_TAG'], pack.IMAGE)

    def test_the_header_total_matches_the_minutes(self):
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        minutes = sum(int(row[3]) for row in order_lines())
        self.assertIn('%d minutes (%d h %d min) in all' % (minutes, minutes // 60, minutes % 60), text)
        for row in order_lines():
            self.assertIn('%s %s' % (row[0].split('-')[0], row[3]), text)

    def test_needs_lines_name_earlier_jobs_only(self):
        names = [row[0].split('-')[0] for row in order_lines()]
        for left_right in directives('# NEEDS '):
            arrow = left_right.index('<-')
            left, right = left_right[:arrow], left_right[arrow + 1:]
            for job_name in left + right:
                self.assertIn(job_name, names)
            for later in left:
                for earlier in right:
                    self.assertLess(names.index(earlier), names.index(later), left_right)
        needed = set(token for line in directives('# NEEDS ') for token in line[:line.index('<-')])
        self.assertTrue({'X0', 'W0', 'SW1', 'T2', 'L1', 'L2', 'SA1'} <= needed)

    def test_the_arc_range_covers_every_swift_boot_and_the_timed_jobs(self):
        names = [row[0].split('-')[0] for row in order_lines()]
        (first, last), = directives('# ARC-ZERO ')
        self.assertEqual((first, last), ('W0', 'SA1'))
        for token in ('W0', 'SW1', 'SB1', 'T1', 'T2', 'C1', 'L1', 'C2', 'L2', 'SA1'):
            self.assertTrue(names.index(first) <= names.index(token) <= names.index(last), token)
        for token in ('B0', 'X0', 'Z'):
            self.assertFalse(names.index(first) <= names.index(token) <= names.index(last), token)


class TemplateTests(unittest.TestCase):
    def test_every_template_parses_with_rc_0(self):
        for name in EXPECTED:
            with self.subTest(name=name):
                code, text = run_reader(PACK / (name + '.env'))
                self.assertEqual(code, 0, text)

    def test_swift_jobs_carry_the_checkpoint_keys_and_base_jobs_carry_neither(self):
        for name, (_mode, serves_swift, profile, tests) in EXPECTED.items():
            with self.subTest(name=name):
                found = values(name)
                if serves_swift:
                    self.assertEqual((found['C2_MODEL_REPO'], found['C2_MODEL_REVISION']), (SWIFT['repo'], SWIFT['revision']))
                else:
                    self.assertNotIn('C2_MODEL_REPO', found)
                    self.assertNotIn('C2_MODEL_REVISION', found)
                self.assertEqual(found.get('C2_PROFILE', ''), profile)
                self.assertEqual(found.get('C2_SMOKE_TESTS', ''), tests)

    def test_the_outputs_the_workflow_reads(self):
        for name, (_mode, serves_swift, _profile, _tests) in EXPECTED.items():
            code, text = run_reader(PACK / (name + '.env'))
            outputs = dict(line.split('=', 1) for line in text.splitlines() if '=' in line)
            with self.subTest(name=name):
                self.assertEqual(outputs['model_repo'], SWIFT['repo'] if serves_swift else '')
                self.assertEqual(outputs['model_served'], 'ukisai/Swift-1.5-Qwen3.8-27b' if serves_swift else '')

    def test_each_smoke_job_names_the_steady_test_and_a_box_inside_the_step(self):
        for name, (_mode, _swift, profile, tests) in EXPECTED.items():
            found = values(name)
            if 'smoke' not in found['C2_ACTIONS'].split():
                continue
            with self.subTest(name=name):
                self.assertIn('concurrent8_steady', tests.split(','))
                self.assertTrue(0 < int(found['C2_BOX_MINUTES']) <= 210)
                self.assertEqual(found['C2_CARDS'], 'quad')
                self.assertEqual(found['C2_TELEMETRY'], '1')

    def test_no_job_uses_a_step_that_does_not_forward_the_checkpoint(self):
        for name in EXPECTED:
            actions = set(values(name)['C2_ACTIONS'].split())
            if values(name).get('C2_MODEL_REPO'):
                self.assertFalse(actions - set(job.MODEL_ACTIONS), name)
            self.assertFalse(actions & {'gate', 'prefix', 'replay', 'push', 'agentstop', 'agentstart', 'unserve', 'platform'}, name)

    def test_the_build_bakes_the_approved_ship_profile_with_the_oneq_graft(self):
        found = values('B0-build-window')
        self.assertEqual((found['C2_BAKE_DEFAULT_PROFILE'], found['C2_BAKE_GRAFT']), (pack.SHIP, 'K64j-OQ'))
        entry = json.loads(PROFILES.read_text(encoding='utf-8'))['profiles'][pack.SHIP]
        self.assertFalse(job.bake_waiver_pending(entry), 'the ship-4 waiver is APPROVED: the build is not refused')

    def test_the_tau_pair_uses_one_profile_and_the_lab_arms(self):
        base, swift = values('T1-tau-base'), values('T2-tau-swift')
        for key in ('C2_TAULAB_PROFILE', 'C2_TAULAB_IN_FLIGHT'):
            self.assertEqual(base[key], swift[key])
        self.assertEqual(base['C2_TAULAB_ARMS'].split(), ['A3', 'A1', 'A2'])
        self.assertEqual(swift['C2_TAULAB_ARMS'].split(), ['A1', 'A2'])
        self.assertNotIn('C2_TAULAB_DRAFTER_ARM', swift, 'the drafter is the base\'s in both runs')
        self.assertLessEqual(int(base['C2_TAULAB_DEADLINE']), job.MAX_TAULAB_DEADLINE_MINUTES)

    def test_the_decode_pairs_run_the_same_tests_on_the_same_profile(self):
        keys = ('C2_PROFILE', 'C2_SMOKE_TESTS', 'C2_BOX_MINUTES', 'C2_IMAGE_TAG')
        for control, arm in (('C1-base-a', 'L1-swift-a'), ('C2-base-b', 'L2-swift-b')):
            self.assertEqual([values(control)[key] for key in keys], [values(arm)[key] for key in keys])
        self.assertEqual(values('C1-base-a')['C2_SMOKE_TESTS'], 'warmup,concurrent8_steady,concurrent8_code_32k_long')


class GeneratedTests(unittest.TestCase):
    def test_the_checked_in_pack_is_what_the_generator_makes(self):
        self.assertEqual(pack.main(['--check']), 0)

    def test_nothing_in_the_pack_names_a_host_an_address_or_a_registry(self):
        for path in PACK.glob('*'):
            text = path.read_text(encoding='utf-8')
            with self.subTest(path=path.name):
                self.assertEqual([needle for needle in ('/home/', 'zot.', 'ghcr', 'docker.io', '.local', '.internal', 'localhost') if needle in text], [])
                self.assertIsNone(re.search(r'\b(?:\d{1,3}\.){3}\d{1,3}\b', text), 'an IP address')
                self.assertIsNone(re.search(r'blackhole-[0-9A-F]{16}', text), 'a card id')
                self.assertIsNone(re.search(r'\bsha256:[0-9a-f]{12,}', text), 'an image digest')


if __name__ == '__main__':
    unittest.main()
